// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        address currentOwner = c.owner();
        vm.assume(caller != currentOwner);

        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // reference: non-owner caller cannot change owner
            assertTrue(c.owner() == currentOwner);
        } catch {
            // reference: call may revert for a non-owner; owner must stay unchanged
            assertTrue(c.owner() == currentOwner);
        }
    }
}
